python:
R = {(1, "DB"), (1, "OS"), (2, "DB")}
S = {("DB", 101), ("OS", 102), ("ML", 103)}
assert len(R) * len(S) == 9
db = {row for row in S if row[0] == "DB"}
join = {(sid, cid, room) for sid, cid in R for code, room in db if cid == code}
direct = {sid for sid, cid in R if cid == "DB"}
assert direct == {sid for sid, cid, room in join} == {1, 2}
assert len(join) == 2
diff = {sid for sid, cid in R} - {sid for sid, cid in R if cid != "DB"}
assert diff == {2}
full_join = {(sid, cid, room) for sid, cid in R for code, room in S if cid == code}
assert full_join == {(1, "DB", 101), (1, "OS", 102), (2, "DB", 101)}
assert len(full_join) == 3
names = {("Ada", "CS"), ("Ada", "EE"), ("Bo", "CS")}
kept = {n for n, d in names if d == "CS"}
bad = {n for n, d in names} - {n for n, d in names if d != "CS"}
assert kept == {"Ada", "Bo"} and bad == {"Bo"}
print(len(R) * len(S), len(full_join), sorted(diff))
